let _markdown = "\n\n<FeedbackBlock id=\"5d1b0f5f2bdfd0b8\" body=\"To begin, create an account on Orama Cloud.\">\n  To begin, create an account on Orama Cloud.\n</FeedbackBlock>\n\nREST API [#rest-api]\n\n<FeedbackBlock id=\"23d152afbac315ca\" body=\"REST API integration requires your docs to upload the indexes.\">\n  REST API integration requires your docs to upload the indexes.\n</FeedbackBlock>\n\n<FeedbackBlock\n  id=\"884bd76f9d954826\"\n  body=\"Create a new project with REST API data source on Orama Cloud dashboard.Store your credentials in environment variables, for example:NEXT_PUBLIC_ORAMA_DATASOURCE_ID=&#x22;Rest API data source ID&#x22;\nNEXT_PUBLIC_ORAMA_PROJECT_ID=&#x22;project ID&#x22;\nNEXT_PUBLIC_ORAMA_API_KEY=&#x22;public API key&#x22;\n\nORAMA_PRIVATE_API_KEY=&#x22;private API key&#x22;Export the search indexes by pre-rendering a static route.import { source } from '@/lib/source';\nimport type { OramaDocument } from 'fumadocs-core/search/orama-cloud';\n\nexport async function exportSearchIndexes() {\n  return source.getPages().map((page) => {\n    return {\n      id: page.url,\n      structured: page.data.structuredData,\n      url: page.url,\n      title: page.data.title,\n      description: page.data.description,\n    } satisfies OramaDocument;\n  });\n}Next.jsReact RouterTanstack StartWakuimport { exportSearchIndexes } from '@/lib/export-search-indexes';\n\nexport const revalidate = false;\n\nexport async function GET() {\n  return Response.json(await exportSearchIndexes());\n}import { exportSearchIndexes } from '@/lib/export-search-indexes';\n\nexport async function loader() {\n  return Response.json(await exportSearchIndexes());\n}import { route, type RouteConfig } from '@react-router/dev/routes';\n\nexport default [\n  // [!code ++]\n  route('static.json', 'routes/static.ts'),\n] satisfies RouteConfig;import { createFileRoute } from '@tanstack/react-router';\nimport { exportSearchIndexes } from '@/lib/export-search-indexes';\n\nexport const Route = createFileRoute('/static.json')({\n  server: {\n    handlers: {\n      GET: async () => Response.json(await exportSearchIndexes()),\n    },\n  },\n});import { tanstackStart } from '@tanstack/react-start/plugin/vite';\nimport { defineConfig } from 'vite';\n\nexport default defineConfig({\n  plugins: [\n    // ...\n    tanstackStart({\n      prerender: {\n        enabled: true,\n      },\n      // [!code ++] pre-render the static file\n      pages: [{ path: '/static.json' }],\n    }),\n  ],\n});import { exportSearchIndexes } from '@/lib/export-search-indexes';\n\nexport async function GET() {\n  return Response.json(await exportSearchIndexes());\n}\n\nexport const getConfig = () => ({\n  render: 'static',\n});Create a script to sync search indexes.import { sync, type OramaDocument } from 'fumadocs-core/search/orama-cloud';\nimport * as fs from 'node:fs/promises';\nimport { OramaCloud } from '@orama/core';\n\n// the path of pre-rendered `static.json`, choose one according to your React framework\nconst filePath = {\n  next: '.next/server/app/static.json.body',\n  'tanstack-start': '.output/public/static.json',\n  'react-router': 'build/client/static.json',\n  waku: 'dist/public/static.json',\n}['next'];\n\nasync function main() {\n  const orama = new OramaCloud({\n    projectId: process.env.NEXT_PUBLIC_ORAMA_PROJECT_ID,\n    apiKey: process.env.ORAMA_PRIVATE_API_KEY,\n  });\n\n  const content = await fs.readFile(filePath);\n  const records = JSON.parse(content.toString()) as OramaDocument[];\n\n  await sync(orama, {\n    index: process.env.NEXT_PUBLIC_ORAMA_DATASOURCE_ID,\n    documents: records,\n  });\n\n  console.log(`search updated: ${records.length} records`);\n}\n\nvoid main();Run the script after production build, make sure the environment variables are available (e.g. Bun reads from .env files):{\n  &#x22;scripts&#x22;: {\n    &#x22;build&#x22;: &#x22;... && bun scripts/sync-content.ts&#x22;\n  }\n}\"\n>\n  1. Create a new project with **REST API** data source on Orama Cloud dashboard.\n\n     Store your credentials in environment variables, for example:\n\n     ```dotenv\n     NEXT_PUBLIC_ORAMA_DATASOURCE_ID=\"Rest API data source ID\"\n     NEXT_PUBLIC_ORAMA_PROJECT_ID=\"project ID\"\n     NEXT_PUBLIC_ORAMA_API_KEY=\"public API key\"\n\n     ORAMA_PRIVATE_API_KEY=\"private API key\"\n     ```\n\n  2. Export the search indexes by pre-rendering a static route.\n\n     ```ts title=\"lib/export-search-indexes.ts\"\n     import { source } from '@/lib/source';\n     import type { OramaDocument } from 'fumadocs-core/search/orama-cloud';\n\n     export async function exportSearchIndexes() {\n       return source.getPages().map((page) => {\n         return {\n           id: page.url,\n           structured: page.data.structuredData,\n           url: page.url,\n           title: page.data.title,\n           description: page.data.description,\n         } satisfies OramaDocument;\n       });\n     }\n     ```\n\n     <CodeBlockTabs defaultValue=\"Next.js\">\n       <CodeBlockTabsList>\n         <CodeBlockTabsTrigger value=\"Next.js\">\n           Next.js\n         </CodeBlockTabsTrigger>\n\n         <CodeBlockTabsTrigger value=\"React Router\">\n           React Router\n         </CodeBlockTabsTrigger>\n\n         <CodeBlockTabsTrigger value=\"Tanstack Start\">\n           Tanstack Start\n         </CodeBlockTabsTrigger>\n\n         <CodeBlockTabsTrigger value=\"Waku\">\n           Waku\n         </CodeBlockTabsTrigger>\n       </CodeBlockTabsList>\n\n       <CodeBlockTab value=\"Next.js\">\n         ```ts  title=\"app/static.json/route.ts\"\n         import { exportSearchIndexes } from '@/lib/export-search-indexes';\n\n         export const revalidate = false;\n\n         export async function GET() {\n           return Response.json(await exportSearchIndexes());\n         }\n         ```\n       </CodeBlockTab>\n\n       <CodeBlockTab value=\"React Router\">\n         ```ts  title=\"app/routes/static.ts\"\n         import { exportSearchIndexes } from '@/lib/export-search-indexes';\n\n         export async function loader() {\n           return Response.json(await exportSearchIndexes());\n         }\n         ```\n\n         ```ts  title=\"app/routes.ts\"\n         import { route, type RouteConfig } from '@react-router/dev/routes';\n\n         export default [\n           // [!code ++]\n           route('static.json', 'routes/static.ts'),\n         ] satisfies RouteConfig;\n         ```\n       </CodeBlockTab>\n\n       <CodeBlockTab value=\"Tanstack Start\">\n         ```ts  title=\"src/routes/static[.]json.ts\"\n         import { createFileRoute } from '@tanstack/react-router';\n         import { exportSearchIndexes } from '@/lib/export-search-indexes';\n\n         export const Route = createFileRoute('/static.json')({\n           server: {\n             handlers: {\n               GET: async () => Response.json(await exportSearchIndexes()),\n             },\n           },\n         });\n         ```\n\n         ```ts  title=\"vite.config.ts\"\n         import { tanstackStart } from '@tanstack/react-start/plugin/vite';\n         import { defineConfig } from 'vite';\n\n         export default defineConfig({\n           plugins: [\n             // ...\n             tanstackStart({\n               prerender: {\n                 enabled: true,\n               },\n               // [!code ++] pre-render the static file\n               pages: [{ path: '/static.json' }],\n             }),\n           ],\n         });\n         ```\n       </CodeBlockTab>\n\n       <CodeBlockTab value=\"Waku\">\n         ```ts  title=\"pages/api/static.json.ts\"\n         import { exportSearchIndexes } from '@/lib/export-search-indexes';\n\n         export async function GET() {\n           return Response.json(await exportSearchIndexes());\n         }\n\n         export const getConfig = () => ({\n           render: 'static',\n         });\n         ```\n       </CodeBlockTab>\n     </CodeBlockTabs>\n\n  3. Create a script to sync search indexes.\n\n     ```ts title=\"scripts/sync-content.ts\"\n     import { sync, type OramaDocument } from 'fumadocs-core/search/orama-cloud';\n     import * as fs from 'node:fs/promises';\n     import { OramaCloud } from '@orama/core';\n\n     // the path of pre-rendered `static.json`, choose one according to your React framework\n     const filePath = {\n       next: '.next/server/app/static.json.body',\n       'tanstack-start': '.output/public/static.json',\n       'react-router': 'build/client/static.json',\n       waku: 'dist/public/static.json',\n     }['next'];\n\n     async function main() {\n       const orama = new OramaCloud({\n         projectId: process.env.NEXT_PUBLIC_ORAMA_PROJECT_ID,\n         apiKey: process.env.ORAMA_PRIVATE_API_KEY,\n       });\n\n       const content = await fs.readFile(filePath);\n       const records = JSON.parse(content.toString()) as OramaDocument[];\n\n       await sync(orama, {\n         index: process.env.NEXT_PUBLIC_ORAMA_DATASOURCE_ID,\n         documents: records,\n       });\n\n       console.log(`search updated: ${records.length} records`);\n     }\n\n     void main();\n     ```\n\n  4. Run the script after production build, make sure the environment variables are available (e.g. Bun reads from `.env` files):\n\n     ```json title=\"package.json\"\n     {\n       \"scripts\": {\n         \"build\": \"... && bun scripts/sync-content.ts\"\n       }\n     }\n     ```\n</FeedbackBlock>\n\nSearch Client [#search-client]\n\n<FeedbackBlock id=\"7e6d90ca5f02b0c6\" body=\"To search documents on the client side, consider:\">\n  To search documents on the client side, consider:\n</FeedbackBlock>\n\n<FeedbackBlock\n  id=\"a442cb7035edcdbf\"\n  body=\"Using Fumadocs UI search dialog.Custom search UI using the built-in hook of Fumadocs:import { useDocsSearch } from 'fumadocs-core/search/client';\nimport { OramaCloud } from '@orama/core';\n\nconst client = new OramaCloud({\n  projectId: process.env.NEXT_PUBLIC_ORAMA_PROJECT_ID,\n  apiKey: process.env.NEXT_PUBLIC_ORAMA_API_KEY,\n});\n\nconst { search, setSearch, query } = useDocsSearch({\n  type: 'orama-cloud',\n  client,\n  params: {\n    // optional search params\n  },\n});Use their search client directly.\"\n>\n  * Using [Fumadocs UI search dialog](/docs/search/orama-cloud).\n\n  * Custom search UI using the built-in hook of Fumadocs:\n\n    ```ts\n    import { useDocsSearch } from 'fumadocs-core/search/client';\n    import { OramaCloud } from '@orama/core';\n\n    const client = new OramaCloud({\n      projectId: process.env.NEXT_PUBLIC_ORAMA_PROJECT_ID,\n      apiKey: process.env.NEXT_PUBLIC_ORAMA_API_KEY,\n    });\n\n    const { search, setSearch, query } = useDocsSearch({\n      type: 'orama-cloud',\n      client,\n      params: {\n        // optional search params\n      },\n    });\n    ```\n\n  * Use their search client directly.\n</FeedbackBlock>\n\nWeb Crawler [#web-crawler]\n\n<FeedbackBlock id=\"2526dba82c2546e8\" body=\"Create a Crawler data source from dashboard, and configure it correctly with the &#x22;Documentation&#x22; preset.Copy the credentials from dashboard.\">\n  1. Create a Crawler data source from dashboard, and configure it correctly with the \"Documentation\" preset.\n  2. Copy the credentials from dashboard.\n</FeedbackBlock>\n\nSearch Client [#search-client-1]\n\n<FeedbackBlock id=\"7b2874720649a7f1\" body=\"Same as REST API integration, but make sure to set index to crawler.\">\n  Same as REST API integration, but make sure to set `index` to `crawler`.\n</FeedbackBlock>\n\n```ts\nimport { useDocsSearch } from 'fumadocs-core/search/client';\nimport { OramaCloud } from '@orama/core';\n\nconst client = new OramaCloud({\n  projectId: '<project id>',\n  apiKey: '<read only api key>',\n});\n\nconst { search, setSearch, query } = useDocsSearch({\n  type: 'orama-cloud',\n  index: 'crawler',\n  client,\n  params: {\n    // optional search params\n  },\n});\n```\n\n<FeedbackBlock id=\"99212232927281a6\" body=\"It's same for Fumadocs UI.\">\n  It's same for Fumadocs UI.\n</FeedbackBlock>\n";
